#!/usr/bin/env python3
"""
Analytics API server for product events insights
Serves three endpoints for frontend team analytics
"""

from flask import Flask, jsonify, request
import clickhouse_connect
from typing import Dict, List, Any

app = Flask(__name__)

# ClickHouse connection
def get_clickhouse_client():
    return clickhouse_connect.get_client(host='localhost', port=8123)

@app.route('/api/top-products', methods=['GET'])
def top_products():
    """
    Get top products by various metrics
    Query parameters:
    - metric: 'views', 'purchases', 'revenue' (default: 'views')
    - limit: number of products to return (default: 10)
    """
    metric = request.args.get('metric', 'views')
    limit = int(request.args.get('limit', 10))

    client = get_clickhouse_client()

    try:
        if metric == 'views':
            query = """
            SELECT product_id, sum(view_count) as total_views
            FROM top_products_by_views
            GROUP BY product_id
            ORDER BY total_views DESC
            LIMIT {}
            """.format(limit)

            result = client.query(query)
            products = [
                {"product_id": row[0], "views": int(row[1])}
                for row in result.result_rows
            ]

        elif metric == 'purchases':
            query = """
            SELECT product_id, sum(purchase_count) as total_purchases
            FROM top_products_by_purchases
            GROUP BY product_id
            ORDER BY total_purchases DESC
            LIMIT {}
            """.format(limit)

            result = client.query(query)
            products = [
                {"product_id": row[0], "purchases": int(row[1])}
                for row in result.result_rows
            ]

        elif metric == 'revenue':
            query = """
            SELECT product_id, sum(total_revenue) as total_revenue
            FROM top_products_by_purchases
            GROUP BY product_id
            ORDER BY total_revenue DESC
            LIMIT {}
            """.format(limit)

            result = client.query(query)
            products = [
                {"product_id": row[0], "revenue": float(row[1]) if row[1] else 0.0}
                for row in result.result_rows
            ]

        else:
            return jsonify({"error": "Invalid metric. Use 'views', 'purchases', or 'revenue'"}), 400

        return jsonify({
            "metric": metric,
            "limit": limit,
            "products": products
        })

    except Exception as e:
        return jsonify({"error": str(e)}), 500
    finally:
        client.close()

@app.route('/api/funnel', methods=['GET'])
def conversion_funnel():
    """
    Get conversion funnel data showing views → carts → purchases
    Returns overall funnel metrics and per-product breakdown
    """
    client = get_clickhouse_client()

    try:
        # Overall funnel metrics
        overall_query = """
        SELECT
            sum(views) as total_views,
            sum(carts) as total_carts,
            sum(purchases) as total_purchases
        FROM conversion_funnel
        """

        result = client.query(overall_query)
        total_views, total_carts, total_purchases = result.result_rows[0]

        # Calculate conversion rates
        view_to_cart_rate = (total_carts / total_views * 100) if total_views > 0 else 0
        cart_to_purchase_rate = (total_purchases / total_carts * 100) if total_carts > 0 else 0
        overall_conversion_rate = (total_purchases / total_views * 100) if total_views > 0 else 0

        # Per-product breakdown
        product_query = """
        SELECT
            product_id,
            sum(views) as views,
            sum(carts) as carts,
            sum(purchases) as purchases
        FROM conversion_funnel
        GROUP BY product_id
        ORDER BY views DESC
        """

        result = client.query(product_query)
        products = []
        for row in result.result_rows:
            product_id, views, carts, purchases = row
            products.append({
                "product_id": product_id,
                "views": int(views),
                "carts": int(carts),
                "purchases": int(purchases),
                "view_to_cart_rate": round((carts / views * 100) if views > 0 else 0, 2),
                "cart_to_purchase_rate": round((purchases / carts * 100) if carts > 0 else 0, 2),
                "overall_conversion_rate": round((purchases / views * 100) if views > 0 else 0, 2)
            })

        return jsonify({
            "overall": {
                "total_views": int(total_views),
                "total_carts": int(total_carts),
                "total_purchases": int(total_purchases),
                "view_to_cart_rate": round(view_to_cart_rate, 2),
                "cart_to_purchase_rate": round(cart_to_purchase_rate, 2),
                "overall_conversion_rate": round(overall_conversion_rate, 2)
            },
            "products": products
        })

    except Exception as e:
        return jsonify({"error": str(e)}), 500
    finally:
        client.close()

@app.route('/api/hourly', methods=['GET'])
def hourly_activity():
    """
    Get activity over time showing hourly event counts
    Query parameters:
    - event_type: filter by event type ('view', 'cart', 'purchase', 'all') (default: 'all')
    """
    event_type = request.args.get('event_type', 'all')

    client = get_clickhouse_client()

    try:
        if event_type == 'all':
            query = """
            SELECT
                hour,
                event_type,
                sum(event_count) as total_events
            FROM hourly_activity
            GROUP BY hour, event_type
            ORDER BY hour, event_type
            """
        else:
            query = """
            SELECT
                hour,
                event_type,
                sum(event_count) as total_events
            FROM hourly_activity
            WHERE event_type = '{}'
            GROUP BY hour, event_type
            ORDER BY hour, event_type
            """.format(event_type)

        result = client.query(query)

        # Group by hour for easier consumption
        hourly_data = {}
        for row in result.result_rows:
            hour, evt_type, count = row
            hour_str = hour.strftime('%Y-%m-%d %H:%M:%S')

            if hour_str not in hourly_data:
                hourly_data[hour_str] = {
                    "hour": hour_str,
                    "events": {}
                }

            hourly_data[hour_str]["events"][evt_type] = int(count)

        # Convert to list and sort by hour
        activity = list(hourly_data.values())
        activity.sort(key=lambda x: x["hour"])

        return jsonify({
            "event_type_filter": event_type,
            "total_hours": len(activity),
            "activity": activity
        })

    except Exception as e:
        return jsonify({"error": str(e)}), 500
    finally:
        client.close()

@app.route('/health', methods=['GET'])
def health_check():
    """Health check endpoint"""
    return jsonify({"status": "healthy", "service": "analytics-api"})

@app.route('/', methods=['GET'])
def root():
    """API documentation"""
    return jsonify({
        "name": "Product Analytics API",
        "version": "1.0",
        "endpoints": {
            "/api/top-products": {
                "method": "GET",
                "description": "Get top products by metric",
                "parameters": {
                    "metric": "views|purchases|revenue (default: views)",
                    "limit": "number of products (default: 10)"
                }
            },
            "/api/funnel": {
                "method": "GET",
                "description": "Get conversion funnel data (views → carts → purchases)"
            },
            "/api/hourly": {
                "method": "GET",
                "description": "Get hourly activity data",
                "parameters": {
                    "event_type": "view|cart|purchase|all (default: all)"
                }
            },
            "/health": {
                "method": "GET",
                "description": "Health check endpoint"
            }
        }
    })

if __name__ == '__main__':
    print("Starting Analytics API server on port 3000...")
    app.run(host='0.0.0.0', port=3000, debug=False)

